from pathlib import Path

p = Path('/opt/wiener-backend/server.mjs')
s = p.read_text()
marker = "\napp.use((_req,res)=>\n  res.status(404).json({ok:false,error:'route_not_enabled_yet'})\n);\n"
TAG = 'WIENER VPS FULL BOT PARITY V18'
if TAG in s:
    print('V18 full bot parity already installed')
    raise SystemExit(0)
if marker not in s:
    raise SystemExit('ERROR: final insertion marker not found')

# Make the consolidated webhook run V18 before the older partial V10B layer.
hook = "    try{if(await handleBotOpsV10B(up,uid,text,m,q)) return done();}catch(e){console.error('v10b_bot_ops',String(e?.message||e));}\n\n"
if hook not in s:
    raise SystemExit('ERROR: V10B webhook hook not found')
s = s.replace(hook, "    try{if(await handleBotFullV18(up,uid,text,m,q)) return done();}catch(e){console.error('v18_bot_ops',String(e?.message||e));}\n" + hook, 1)

# V14 registered generic webhook relays under old bot function names. Disable those
# registrations so V18 can restore their real semantics below.
legacy_list = "['wiener-bot-sync','wiener-bot-router','wiener-bot-start','wiener-user-menu','wiener-bot-leaderboard','wiener-bot-admin','wiener-bot-user-inspector','wiener-bot-broadcast','wiener-bot-addtask','wiener-bot-addtask-target']"
if legacy_list in s:
    s = s.replace(legacy_list, '[]', 1)
else:
    print('WARNING: V14 generic bot relay list not found; continuing')

pay_proxy = "for(const spec of [{route:'wiener-bot-pay',target:'wiener-payout'},{route:'wiener-bot-pay-ton',target:'wiener-ton-payout'}]){"
if pay_proxy in s:
    s = s.replace(pay_proxy, 'for(const spec of []){', 1)
else:
    print('WARNING: V14 bot payout proxy loop not found; continuing')

treasury_410 = "app.all('/functions/v1/wiener-bot-treasury',(_req,res)=>res.status(410).json({ok:false,error:'feature_removed',message:'Treasury Chest has been removed.'}));"
